NAMES = {p["slug"]: p["h1"] for p in PAGES}

def render(p):
    slug = p["slug"]
    url = f"{BASE}/{slug}/"
    h1 = escape(p["h1"])
    nav = "".join(f'<a href="{href}"{(" aria-current=" + chr(34) + "page" + chr(34)) if href == "/" + slug + "/" else ""}>{escape(label)}</a>' for label, href in NAV)
    sections = "".join(f'<section class="content-card"><h2>{escape(head)}</h2><p>{escape(body)}</p></section>' for head, body in p["sections"])
    questions = "" if not p.get("questions") else '<section class="faqs"><h2>Questions families ask</h2>' + "".join(f'<details><summary>{escape(q)}</summary><p>{escape(a)}</p></details>' for q,a in p["questions"]) + '</section>'
    links = "".join(f'<a class="related-link" href="/{s}/">{escape(NAMES[s])} <span aria-hidden="true">↗</span></a>' for s in p.get("related", []))
    refs = "" if not p.get("references") else '<aside class="references"><h2>Further reading</h2><ul>' + "".join(f'<li><a href="{escape(u)}" rel="noopener">{escape(n)}</a></li>' for n,u in p["references"]) + '</ul></aside>'
    photo = '<img class="profile" src="/pp.png" alt="Portrait of Nur Siti Eissya" width="440" height="440" loading="eager">' if p.get("image") else ''
    graph = [
        {"@type":"WebPage","@id":url+"#page","url":url,"name":p["title"],"description":p["description"],"isPartOf":{"@id":BASE+"/#website"},"about":{"@id":BASE+"/#business"}},
        {"@type":"BreadcrumbList","@id":url+"#breadcrumb","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":BASE+"/"},{"@type":"ListItem","position":2,"name":p["h1"],"item":url}]}
    ]
    if slug in ("home-physiotherapy-ipoh", "stroke-rehabilitation-ipoh", "elderly-physiotherapy-ipoh"):
        graph.append({"@type":"Service","@id":url+"#service","name":p["h1"],"provider":{"@id":BASE+"/#business"},"areaServed":{"@type":"City","name":"Ipoh"},"url":url})
    schema = json.dumps({"@context":"https://schema.org","@graph":graph}, ensure_ascii=False).replace("<", "\\u003c")
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#FEFBF9">
<title>{escape(p['title'])}</title><meta name="description" content="{escape(p['description'])}"><link rel="canonical" href="{url}">
<meta property="og:type" content="website"><meta property="og:title" content="{escape(p['title'])}"><meta property="og:description" content="{escape(p['description'])}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}/pp.png">
<link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Fraunces:wght@500;600;700&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/site.css">
<script type="application/ld+json">{schema}</script></head>
<body><a class="skip" href="#main">Skip to content</a><header class="top"><a class="brand" href="/">Eissya<span>•</span>Physio</a><nav aria-label="Main navigation">{nav}</nav><a class="header-cta" href="{WA}" target="_blank" rel="noopener">WhatsApp Eissya</a></header>
<main id="main"><div class="page-hero"><p class="eyebrow">One-to-one care · Ipoh, Perak</p><h1>{h1}</h1><p class="lead">{escape(p['intro'])}</p><div class="actions"><a class="button" href="{WA}" target="_blank" rel="noopener">Ask Eissya on WhatsApp</a><a class="button secondary" href="/pricing/">View prices</a></div></div>
<div class="page-body">{photo}<div class="content-grid">{sections}</div>{questions}<section class="next"><h2>Explore more</h2><div class="related">{links}</div></section>{refs}<section class="final-cta"><h2>Discuss your needs with Eissya</h2><p>Home visits are available within Ipoh. The exact transport fee is confirmed before you book.</p><a class="button" href="{WA}" target="_blank" rel="noopener">Start a WhatsApp enquiry</a></section></div></main>
<footer><a href="/">Eissya Physio</a><span>Home physiotherapy within Ipoh, Perak</span><a href="/contact/">Contact</a><a href="/faq/">FAQs</a><span>© 2026 Nur Siti Eissya</span></footer></body></html>'''

